  CONSTRAINT "chk_employees_email_lowercase" CHECK (email = lower(email)),
  CONSTRAINT "chk_employees_sync_provenance" CHECK ((source in ('api', 'log')) = (sync_run_id is not null)),
  CONSTRAINT "chk_employees_import_provenance" CHECK ((source = 'import') = (import_batch_id is not null))
);

