  CONSTRAINT "chk_contracts_ended_after_start" CHECK (ended_on is null or ended_on >= start_date),
  CONSTRAINT "chk_contracts_notice_period" CHECK (notice_period_days is null or notice_period_days >= 0),
  CONSTRAINT "chk_contracts_currency" CHECK ((total_value is null and commitment_amount is null) or currency is not null),
  CONSTRAINT "chk_contracts_commitment" CHECK (commitment_amount is null or commitment_amount >= 0),
