  CONSTRAINT "chk_usage_records_active_subjects_aggregate" CHECK (metric <> 'active_subjects' or subject_id is null),
  CONSTRAINT "chk_usage_records_whole_counts" CHECK (metric not in ('active_subjects', 'peak_concurrent') or quantity = trunc(quantity)),
  CONSTRAINT "chk_usage_records_sync_provenance" CHECK ((source in ('api', 'log')) = (sync_run_id is not null)),
