-- ---------------------------------------------------------------------------
-- Indexes named in the table notes of elms.dbml
-- ---------------------------------------------------------------------------
CREATE UNIQUE INDEX uq_org_units_pnl_name ON org_units (lower(name)) WHERE parent_id IS NULL;
CREATE UNIQUE INDEX uq_software_categories_root_name ON software_categories (lower(name)) WHERE parent_id IS NULL;
CREATE UNIQUE INDEX uq_software_products_vendor_lower_name ON software_products (vendor_id, lower(name));
CREATE UNIQUE INDEX uq_license_plans_product_lower_name ON license_plans (product_id, lower(name));
CREATE UNIQUE INDEX uq_entitlement_lines_plan_external ON entitlement_lines (license_plan_id, external_ref) WHERE external_ref IS NOT NULL;
CREATE UNIQUE INDEX uq_subjects_vendor_external_id ON subjects (vendor_id, external_id) WHERE external_id IS NOT NULL;
CREATE UNIQUE INDEX uq_license_assignments_open ON license_assignments (license_plan_id, subject_id) WHERE ended_on IS NULL;
DROP INDEX uq_usage_records_period;
CREATE UNIQUE INDEX uq_usage_records_period ON usage_records (license_plan_id, subject_id, metric, period_start, period_end) NULLS NOT DISTINCT;
DROP INDEX uq_plan_unit_daily_snapshots;
CREATE UNIQUE INDEX uq_plan_unit_daily_snapshots ON plan_unit_daily_snapshots (snapshot_date, license_plan_id, org_unit_id) NULLS NOT DISTINCT;
DROP INDEX uq_cost_allocations_period_plan_bucket_unit;
CREATE UNIQUE INDEX uq_cost_allocations_period_plan_bucket_unit ON cost_allocations (accounting_period_id, license_plan_id, bucket, org_unit_id) NULLS NOT DISTINCT;
CREATE UNIQUE INDEX uq_expenses_plan_external ON expenses (license_plan_id, external_ref) WHERE external_ref IS NOT NULL;
DROP INDEX uq_detection_results_run_plan_check_unit;
CREATE UNIQUE INDEX uq_detection_results_run_plan_check_unit ON detection_results (detection_run_id, license_plan_id, check_type, org_unit_id) NULLS NOT DISTINCT;
CREATE UNIQUE INDEX uq_recommendations_open ON recommendations (license_plan_id, type, org_unit_id) NULLS NOT DISTINCT WHERE status IN ('proposed', 'accepted');
CREATE UNIQUE INDEX uq_data_overrides_active ON data_overrides (entity_type, entity_id, field_name) WHERE reverted_at IS NULL;
